import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"45、【萃】 坤下兌上","description":"周易口訣義 - 45、【萃】 坤下兌上","frontmatter":{"title":"45、【萃】 坤下兌上","description":"周易口訣義 - 45、【萃】 坤下兌上"},"headers":[],"relativePath":"classics/koujueyi/047.md","filePath":"classics/koujueyi/047.md"}'),r={name:"classics/koujueyi/047.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_45、【萃】-坤下兌上" tabindex="-1">45、【萃】 坤下兌上 <a class="header-anchor" href="#_45、【萃】-坤下兌上" aria-label="Permalink to “45、【萃】 坤下兌上”">​</a></h1><p>彖曰：萃，聚也。順以說，剛中而應，故聚也。「王假有廟」，致孝享也。「利見大人亨」，聚以正也。用大牲吉，利有攸往，順天命也。觀其所聚，而天地萬物之情可見矣。</p><p>象曰：澤上於地，萃。君子以除戎器，戒不虞。</p><p>初六：有孚不終，乃亂乃萃，若號，一握為笑，勿恤，往無咎。</p><p>象曰：「乃亂乃萃」，其志亂也。</p><p>六二：引吉，無咎。孚乃利用礿。</p><p>象曰：「引吉無咎」，中未變也。</p><p>六三：萃如嗟如，無攸利。往無咎，小吝。</p><p>象曰：「往無咎」，上巽也。</p><p>九四：大吉，無咎。</p><p>象曰：「大吉無咎」，位不當也。</p><p>九五：萃有位，無咎，匪孚，元永貞，悔亡。</p><p>象曰：「萃有位」，志未光也。</p><p>上六，齎諮涕洟，無咎。</p><p>象曰：「齎諮涕洟」，未安上也。</p><p>解讀</p><p>「萃亨」者，萃，聚也，其猶王者有德，懷來萬邦，人皆歸之，故曰「萃」也。人既歸己，即無所不通，故曰「萃亨」也。「王假有廟」者，假，至也，天下離散，雖則有廟，與無廟同，縱使享祭，神明不降。今王既有德，人神大同，孝德乃洽，王至此時，始可假有宗廟，故周弘正雲：「鬼神享德，不在食也。」「利見大人，亨，利貞」者，當聚之時，必須德大之人而為其主，故書雲：「惟天生民有欲，無主乃亂」，故曰「利見大人」也。大德之人，能弘正道，即使下民亨通而利以為正，故曰「亨利貞」也。用大牲吉，利有攸往者，大牲，犧牛也；大德之人而為其主，聚道既全，即宜用大牲吉，利用攸往也。象曰「澤上於地，萃」者，澤處地上，水潦聚物，是萃聚象也。「君子以除戎器，戒不虞」者，除，治也，當大聚之時，慮恐人心有異，故曰君子亦修戎器，戒慎防備不虞，文聚武備是也。</p><p>「初六，有孚不終，乃亂乃萃，若號，一握為笑，勿恤，往無咎」者，初六應於九四，見六三與九四相近，心生嫌疑，始以誠信相就，忽然生疑未進，故曰「有孚不終」也。當萃之時，貴於合會，奔馳而往，進不以禮，故曰「乃亂乃萃」。夫謙恭之道，百行之本，若以謙而行，即無不合。今初六若執此謙遜，自比身雲一握之小，又為柔懦卑劣之容，即六三邪偶，安能固守於四？即初六往必相得，不用憂慮，所以「無咎」，故曰「勿恤，往無咎」也。一握者，卑小之質，喻己身如一握之微小也；為笑者，懦劣之容，不敢作強剛之貌也。</p><p>「六二，引吉，無咎，孚乃利用礿」者，礿，殷春祭名，四時最薄也。處聚之時，貴相聚集，方始合宜。今六二體柔居坤，守中不變，意欲靜退，不肯相從，以為聚會，斯乃違眾，時即兇危必至，必須牽引，然後始行，遂得吉而免咎，故曰「引吉，無咎」。以六二體中懷信，不求苟進，既有斯德，即可以往，至薄之物，薦於鬼神，鬼神降福，故曰「孚乃利用礿」也。</p><p>「六三，萃如嗟如，無攸利，往無咎，小吝」者，六三與九四不正，不正相聚，陰邪之應，患必生焉，故乃憂嗟而無所利，故曰「萃如，無攸利」。然上六與三本是正應，上六懷巽之道，以求朋友，故六三可以往而無咎，與上合志而無所咎，故「往無咎」。然上六與三俱是陰柔，雖是相應，俱失其匹配之義，故有「小吝」也。九四，大吉，無咎。居位不正，又下據三陰，即擅君之權，禍咎將至，必須立大功以補其過，可以免咎，故曰「大吉，無咎」。</p><p>「九五，萃有位，無咎，匪孚，元永貞，悔亡」者，處聚之時，最得盛位，故曰「萃有位」也。九四下據三陰，專制己權，己所宣命，人不信服，但自守而已，故曰「無咎，匪孚」也。若能不與物競，但自克修仁德，久而獲福，即憂悔可銷，故曰「元永貞悔亡」。</p><p>「上六：齎諮涕洟無咎」者，齎諮，嗟嘆辭也。居萃之極，乘剛居上，內無應援，則憂患生焉，故齎諮涕泣不安。如此憂懼，即眾所不害，遂將免咎，故曰「無咎」。先儒雲：「自目曰涕，自鼻曰洟。」</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
